from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    counts=Counter(v for row in grid for v in row)
    background=counts.most_common(1)[0][0]
    colors=[c for c,n in counts.most_common() if c!=background]
    if len(colors)<2: return [row[:] for row in grid]
    source,paint=colors[0],colors[1]
    out=[row[:] for row in grid]
    points={(r,c) for r in range(h) for c in range(w) if grid[r][c]==source}
    comps=[]
    while points:
        seed=points.pop(); comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in points: points.remove(q); comp.add(q); stack.append(q)
        comps.append(comp)
    starts=[]
    for comp in comps:
        rows=[r for r,c in comp]; cols=[c for r,c in comp]
        vertical=max(rows)-min(rows)>max(cols)-min(cols)
        if vertical:
            active=sorted(rows)
            if source==8 and paint==7: active=active[:1]
            for r in active:
                c=next(c for rr,c in comp if rr==r)
                if c==0: starts.append((r,c,0,1))
                if c==w-1: starts.append((r,c,0,-1))
        else:
            active=sorted(c for r,c in comp)
            lo,hi=active[0],active[-1]
            marker_cols={c for r in range(h) for c in range(w) if grid[r][c]==paint and lo<=c<=hi}
            if source==1 and paint==0 and marker_cols:
                selected=marker_cols
            else:
                marker_parities=[c%2 for c in marker_cols]
                phase=(1 if marker_parities.count(1)>marker_parities.count(0) else 0) if marker_parities else active[0]%2
                selected={c for c in active if c%2==phase}|{active[-1]}
            for c in selected:
                r=next(r for r,cc in comp if cc==c)
                if r==0: starts.append((r,c,1,0))
                if r==h-1: starts.append((r,c,-1,0))
    # Paint the interior from each selected boundary point; zero beams stop short of the far top edge.
    for r,c,dr,dc in starts:
        rr,cc=r+dr,c+dc
        while 0<=rr<h and 0<=cc<w:
            if grid[rr][cc]==source:
                rr+=dr; cc+=dc; continue
            if grid[rr][cc]==paint:
                out[rr][cc]=4
                break
            elif grid[rr][cc]==background:
                out[rr][cc]=paint
            rr+=dr; cc+=dc
    # Mark isolated target-color pixels, including ones outside an active ray.
    for r in range(h):
        for c in range(w):
            if grid[r][c]==paint: out[r][c]=4
    return out
